  if(/^0[0-7]\d{3}$/.test(s)&&(!buoy||+s[1]<=1))put(out,'sea_temperature',r,(+s[1]%2?-1:1)*+s.slice(2)/10,'°C',{note:'Reported sea-surface temperature'});
